206	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
207	        "NSW", new int[] {2000, 2099},
208	        "VIC", new int[] {3000, 3099},
209	        "QLD", new int[] {4000, 4099});
