211	    /**
212	     * The owner's region, derived on read. The postcode is preferred: a 4-digit postcode falling in a
213	     * known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}) yields
214	     * that region. When the postcode is absent or in no known range, it falls back to the fixed
215	     * city-to-region table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}).
216	     * Returns {@code "UNKNOWN"} when neither source resolves a region.
217	     */
218	    @Transient
219	    public String getRegion() {
220	        String byPostcode = regionForPostcode(this.postcode);
221	        if (byPostcode != null) {
222	            return byPostcode;
223	        }
224	        if ("Sydney".equals(this.city)) {
225	            return "NSW";
226	        }
227	        if ("Melbourne".equals(this.city)) {
228	            return "VIC";
229	        }
