236	    /** The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
237	     *  absent, not a 4-digit value, or in no known range. */
238	    private static String regionForPostcode(String postcode) {
239	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
240	            return null;
241	        }
242	        int value = Integer.parseInt(postcode);
243	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
244	            int[] range = entry.getValue();
245	            if (value >= range[0] && value <= range[1]) {
246	                return entry.getKey();
247	            }
248	        }
249	        return null;
250	    }
