252	    /** The single Luhn check digit (0-9) over the decimal digits contained in {@code value}, scanning
253	     *  right to left and doubling every second digit; non-digit characters are ignored and a null or
254	     *  digit-free value yields {@code 0}. */
255	    private static int luhnCheckDigit(String value) {
256	        int sum = 0;
257	        boolean doubling = true;
258	        for (int i = (value == null ? 0 : value.length()) - 1; i >= 0; i--) {
259	            char c = value.charAt(i);
260	            if (c < '0' || c > '9') {
261	                continue;
262	            }
263	            int digit = c - '0';
264	            if (doubling) {
265	                digit *= 2;
266	                if (digit > 9) {
267	                    digit -= 9;
268	                }
269	            }
270	            sum += digit;
271	            doubling = !doubling;
272	        }
273	        return (10 - (sum % 10)) % 10;
274	    }
